window.B0B_INTRO_CHAPTERS=[{"id": "I", "title": "The record", "year": "1945", "at": 0.0, "end": 24.0, "map": false, "lines": [{"text": "Nuremberg, 1945."}, {"text": "The prosecution did not argue from rumour."}, {"text": "It put the documents on the table, drew the structure of a state on a board, and entered it as an exhibit."}, {"text": "Anyone in the room could check it."}, {"text": "That is the oldest rule in this archive, and the only method this report claims: show the record, say where it came from, and let the reader test it."}]}, {"id": "II", "title": "The instrument", "year": "1947", "at": 24.0, "end": 48.3, "map": false, "lines": [{"text": "Washington, 1947."}, {"text": "A committee of Congress turned its instrument on citizens, and the newsreel cameras came with it."}, {"text": "Whether an inquiry is looking for facts or for a target is not settled by calling it a hearing."}, {"text": "It is settled by one question: could the finding have come out the other way?"}]}, {"id": "III", "title": "The capability", "year": "1952", "at": 48.3, "end": 79.8, "map": false, "lines": [{"text": "Enewetak Atoll, 1952."}, {"text": "The first full-scale test of a thermonuclear device."}, {"text": "The capability arrives before the argument about what it is for."}, {"text": "This report records what a document establishes about a capability, and stops there."}, {"text": "Secrecy is evidence of nothing about what is hidden."}]}, {"id": "IV", "title": "The overhead", "year": "1958", "at": 79.8, "end": 109.8, "map": false, "lines": [{"text": "Cape Canaveral, 1958. The first American satellite."}, {"text": "It carried a cosmic-ray counter, not a camera."}, {"text": "The watching came two years later, under another name, and stayed classified for thirty-five."}, {"text": "A launch is documented the day it happens. What a thing is for is documented separately, by a different kind of paper, often decades later."}]}, {"id": "V", "title": "The annotation", "year": "1962", "at": 109.8, "end": 140.3, "map": false, "lines": [{"text": "October, 1962."}, {"text": "A reconnaissance photograph becomes evidence the moment somebody labels it."}, {"text": "Three missile trailers. Cylindrical object."}, {"text": "The label is the claim, and the label is the part that has to be checked."}, {"text": "That is true of every caption in this report, including the ones on this film."}]}, {"id": "VI", "title": "The public", "year": "1967", "at": 140.3, "end": 167.3, "map": false, "lines": [{"text": "April, 1967."}, {"text": "Thousands against the war, and, in the same reel, their opponents, with placards of their own. The newsreel filmed both."}, {"text": "Discount the evidence that hurts your case exactly as hard as the evidence that helps it."}, {"text": "A crowd is testimony: evidence of an experience, never, by itself, evidence of a cause."}]}, {"id": "VII", "title": "The inquiry", "year": "1987", "at": 167.3, "end": 178.8, "map": false, "lines": [{"text": "Washington, 1987. The inquiry, afterwards."}, {"text": "Everything in this report arrived the same way: late, in public, and on the record."}]}, {"id": "VIII", "title": "The ledger", "year": "2026", "at": 178.8, "end": null, "map": true, "lines": [{"text": "{TOTAL} documented sites. Twenty-five sections.", "say": "{TOTALWORDS} documented sites. Twenty-five sections."}, {"text": "Every source named. Every tier stated."}, {"text": "The specimens it could not prove, killed on its own page."}, {"text": "The authority of a document does not come from what it alleges."}, {"text": "It comes from what it refuses to allege."}, {"text": "τετέλεσται — it has been completed, and remains so.", "say": "Teh-teh-less-tie. It has been completed, and it remains so."}]}];
